#include <memory>
#include <iostream>

class ResourceOwner {
public:
    // Resource is acquired upon construction
    ResourceOwner() : data_(new int(42)) {
        std::cout << "Owner created." << std::endl;
    }
    // No explicit destructor needed; auto_ptr handles cleanup

    int getValue() const { return *data_; }

private:
    std::auto_ptr<int> data_;
    // Note: Copying ResourceOwner would be dangerous due to data_ transfer
};

int main() {
    { // Scope starts
        ResourceOwner ro;
        std::cout << "Value: " << ro.getValue() << std::endl;
    } // Scope ends, ro is destroyed, data_ is deleted automatically
    std::cout << "Resource cleaned up." << std::endl;
    return 0;
}
